implements(Key) :-
    citation(Key, _).

test(a_recorded_key_is_implemented) :-
    implements(eu_reg_2024_1774_art_13_e).
test(the_gate_key_is_implemented) :-
    implements(eu_reg_2022_2554_art_16_1).
test(thirty_six_keys_are_recorded) :-
    findall(Key, citation(Key, _), Keys),
    length(Keys, 36).

test(a_shortened_key_is_not_implemented, fail) :-
    implements(art_13_e).
